import time

RETRY_LIMIT = 3


def run_once(queue, handler):
    task = queue.pop()
    if task is None:
        return False
    attempts = 0
    while attempts < RETRY_LIMIT:
        try:
            handler(task)
            return True
        except Exception:
            attempts += 1
            time.sleep(0.1)
    return False

